      }

      .radio-card:focus-within {
        border-color: var(--accent-strong);
        box-shadow: 0 0 0 3px rgba(251, 191, 36, 0.22);
      }

      .radio-card input {
        margin-top: 0.15rem;
        width: 1.1rem;
        height: 1.1rem;
        accent-color: var(--accent);
      }

      .choice-copy {
        display: grid;
        gap: 0.15rem;
      }

      .choice-title {
        font-weight: 650;
      }

      .choice-description {
