        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        font: inherit;
        font-weight: 700;
        color: #0f172a;
        background: linear-gradient(135deg, #c4b5fd, #8b5cf6);
        box-shadow: 0 12px 30px rgba(139, 92, 246, 0.28);
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
        filter: brightness(1.02);
      }

      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: #cbd5e1;
        font-size: 0.95rem;
      }

      .status[data-state="success"] {
        color: #86efac;
      }

      @media (max-width: 480px) {
        .card {
          padding: 1.25rem;
          border-radius: 1.1rem;
        }

        .form-field {
          padding: 1rem;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <div class="page-shell" id="app"></div>
    </main>

    <script>
      const notificationChoices = [
        {
          value: "email",
          title: "Email",
          description: "Get updates in your inbox."
        },
        {
          value: "sms",
          title: "SMS",
          description: "Receive text messages on your phone."
        },
        {
          value: "push",
          title: "Push Notifications",
          description: "See alerts directly on your device."
        }
      ];

      function RadioOption({ id, value, title, description }) {
        return `
          <label class="radio-card" for="${id}">
            <input id="${id}" name="notification-preference" type="radio" value="${value}" required />
            <span class="choice-copy">
              <span class="choice-title">${title}</span>
              <span class="choice-description">${description}</span>
            </span>
          </label>
        `;
      }

      function NotificationPreferencesForm() {
        return `
          <section class="card" aria-labelledby="notification-title">
            <p class="eyebrow">Preferences</p>
            <h1 id="notification-title">Notification delivery</h1>
            <p class="intro">Choose exactly one way you want to receive notifications.</p>

            <form id="notification-form" novalidate>
              <div class="form-field">
                <fieldset aria-describedby="notification-help">
                  <legend>How do you prefer to receive notifications? <span class="required-mark" aria-hidden="true">*</span></legend>
                  <p class="help-text" id="notification-help">Pick one option so we can keep you updated in the way that works best for you.</p>

                  <div class="choices">
                    ${notificationChoices
                      .map((choice) =>
                        RadioOption({
                          id: `notification-${choice.value}`,
                          value: choice.value,
                          title: choice.title,
                          description: choice.description
                        })
                      )
                      .join("")}
                  </div>
                </fieldset>
              </div>

              <div class="actions">
                <button type="submit">Send preferences</button>
                <p class="status" id="form-status" aria-live="polite">No preference selected yet.</p>
              </div>
            </form>
          </section>
        `;
      }

      document.getElementById("app").innerHTML = NotificationPreferencesForm();

      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const selected = form.elements["notification-preference"].value;
        const selectedLabel = notificationChoices.find((choice) => choice.value === selected)?.title;

        status.textContent = selectedLabel
          ? `Preferences saved: ${selectedLabel}.`
          : "Choose a notification method before sending.";
        status.dataset.state = selectedLabel ? "success" : "error";
      });
    </script>
  </body>
</html>
